const tallyBroadcastRecipients = `-- name: TallyBroadcastRecipients :one
SELECT
    count(*) AS total,
    count(*) FILTER (WHERE status = 'queued') AS queued,
    count(*) FILTER (WHERE sent_at IS NOT NULL) AS sent,
    count(*) FILTER (WHERE delivered_at IS NOT NULL AND status NOT IN ('bounced', 'complained', 'failed')) AS delivered,
    count(*) FILTER (WHERE opened_at IS NOT NULL) AS opened,
    count(*) FILTER (WHERE clicked_at IS NOT NULL) AS clicked,
    count(*) FILTER (WHERE replied_at IS NOT NULL) AS replied,
    count(*) FILTER (WHERE reacted_at IS NOT NULL) AS reacted,
    coalesce(sum(reactions), 0)::bigint AS reactions,
    count(*) FILTER (WHERE unsubscribed_at IS NOT NULL) AS unsubscribed,
    count(*) FILTER (WHERE converted_at IS NOT NULL) AS converted,
    count(*) FILTER (WHERE status = 'failed') AS failed,
    count(*) FILTER (WHERE status = 'bounced') AS bounced,
    count(*) FILTER (WHERE status = 'complained') AS complained,
    count(*) FILTER (WHERE status = 'suppressed') AS suppressed,
    count(*) FILTER (WHERE status = 'skipped') AS skipped,
    count(*) FILTER (WHERE status = 'recalled') AS recalled
FROM broadcast_recipients WHERE workspace_id = $1 AND broadcast_id = $2
`

type TallyBroadcastRecipientsParams struct {
	WorkspaceID ids.UUID `json:"workspace_id"`
	BroadcastID ids.UUID `json:"broadcast_id"`
}

type TallyBroadcastRecipientsRow struct {
	Total        int64 `json:"total"`
	Queued       int64 `json:"queued"`
	Sent         int64 `json:"sent"`
	Delivered    int64 `json:"delivered"`
	Opened       int64 `json:"opened"`
	Clicked      int64 `json:"clicked"`
	Replied      int64 `json:"replied"`
	Reacted      int64 `json:"reacted"`
	Reactions    int64 `json:"reactions"`
	Unsubscribed int64 `json:"unsubscribed"`
	Converted    int64 `json:"converted"`
	Failed       int64 `json:"failed"`
	Bounced      int64 `json:"bounced"`
	Complained   int64 `json:"complained"`
	Suppressed   int64 `json:"suppressed"`
	Skipped      int64 `json:"skipped"`
	Recalled     int64 `json:"recalled"`
}

// TallyBroadcastRecipients counts what happened to a broadcast's
// recipients.
func (q *Queries) TallyBroadcastRecipients(ctx context.Context, arg TallyBroadcastRecipientsParams) (TallyBroadcastRecipientsRow, error) {
	row := q.db.QueryRow(ctx, tallyBroadcastRecipients, arg.WorkspaceID, arg.BroadcastID)
	var i TallyBroadcastRecipientsRow
	err := row.Scan(
		&i.Total,
		&i.Queued,
		&i.Sent,
		&i.Delivered,
		&i.Opened,
		&i.Clicked,
		&i.Replied,
		&i.Reacted,
		&i.Reactions,
		&i.Unsubscribed,
		&i.Converted,
		&i.Failed,
		&i.Bounced,
		&i.Complained,
		&i.Suppressed,
		&i.Skipped,
		&i.Recalled,
	)
	return i, err
}

